import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { FiLogOut, FiUser } from "react-icons/fi"; // Icônes utilisateur + logout

const Navbar = ({ token, setToken, user }) => {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false); // état du menu déroulant

  const handleLogout = () => {
    localStorage.removeItem("token");
    setToken("");
    navigate("/login");
  };

  return (
    <nav
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "15px 40px",
        backgroundColor: "#222",
        color: "#fff",
        position: "relative",
      }}
    >
      {/* === Liens à gauche === */}
      <div style={{ display: "flex", gap: "20px" }}>
        <Link to="/" style={{ color: "#fff", textDecoration: "none" }}>
          🏠 Accueil
        </Link>
        <Link to="/movies" style={{ color: "#fff", textDecoration: "none" }}>
          🎬 Films
        </Link>
      </div>

      {/* === Zone utilisateur à droite === */}
      <div style={{ display: "flex", alignItems: "center", position: "relative" }}>
        {!token ? (
          <>
            <Link
              to="/login"
              style={{ color: "#61dafb", textDecoration: "none", marginRight: "15px" }}
            >
              Se connecter
            </Link>
            <Link
              to="/register"
              style={{ color: "#61dafb", textDecoration: "none" }}
            >
              S’inscrire
            </Link>
          </>
        ) : (
          <div style={{ position: "relative" }}>
            {/* Bouton nom utilisateur */}
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              style={{
                background: "none",
                border: "none",
                color: "#fff",
                fontSize: "16px",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              <FiUser size={20} />
              {user?.username || "Mon Compte"}
            </button>

            {/* Menu déroulant */}
            {menuOpen && (
              <div
                style={{
                  position: "absolute",
                  top: "35px",
                  right: 0,
                  backgroundColor: "#333",
                  borderRadius: "8px",
                  padding: "10px",
                  boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
                  zIndex: 10,
                  minWidth: "160px",
                }}
              >
                <Link
                  to="/profile"
                  style={{
                    display: "block",
                    color: "#fff",
                    textDecoration: "none",
                    padding: "8px",
                    borderRadius: "5px",
                  }}
                  onClick={() => setMenuOpen(false)}
                >
                  👤 Mon compte
                </Link>

                <button
                  onClick={handleLogout}
                  style={{
                    background: "none",
                    border: "none",
                    color: "#ff4d4d",
                    display: "flex",
                    alignItems: "center",
                    gap: "6px",
                    padding: "8px",
                    width: "100%",
                    cursor: "pointer",
                    borderRadius: "5px",
                  }}
                >
                  <FiLogOut size={18} />
                  Déconnexion
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;


